// TMDBMovies.js
import React, { useState, useEffect } from 'react';

function TMDBMovies() {
  const [movies, setMovies] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const API_KEY = "a811f5125a024eaec27cf8e31e3e1fb6";
    // Fetch trending movies for the week from TMDB
    fetch(`https://api.themoviedb.org/3/trending/movie/week?api_key=${API_KEY}`)
      .then((response) => {
        if (!response.ok) {
          throw new Error("Failed to fetch movies");
        }
        return response.json();
      })
      .then((data) => {
        setMovies(data.results);
        setLoading(false);
      })
      .catch((err) => {
        setError(err);
        setLoading(false);
      });
  }, []);

  if (loading) return <div className="tmdb-container"><h1>Trending Movies</h1><p>Loading...</p></div>;
  if (error) return <div className="tmdb-container"><h1>Trending Movies</h1><p>Error: {error.message}</p></div>;

  return (
    <div className="tmdb-container" style={{ padding: "20px", textAlign: "center" }}>
      <h1>Trending Movies (TMDB)</h1>
      <ul style={{ listStyle: "none", padding: 0 }}>
        {movies.map((movie) => (
          <li key={movie.id} style={{ margin: "20px 0", padding: "10px", border: "1px solid #ddd", borderRadius: "5px" }}>
            <h3>{movie.title}</h3>
            <p>{movie.overview}</p>
          </li>
        ))}
      </ul>
    </div>
  );
}

export default TMDBMovies;
